  \"description\": \"CRUD operations on Azure Blob Storage using TypeScript\",\r\n  \"main\": \"dist/index.js\",\r\n  \"scripts\": {\r\n    \"build\": \"tsc\",\r\n    \"start\": \"tsc \u0026\u0026 node dist/index.js\"\r\n  },\r\n  \"dependencies\": {\r\n    \"@azure/storage-blob\": \"^12.26.0\",\r\n    \"@azure/identity\": \"^4.6.0\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"typescript\": \"^5.7.0\",\r\n    \"@types/node\": \"^22.0.0\"\r\n  }\r\n}\r\n\n```\n\n### src\\index.ts\n```\nimport {\r\n  BlobServiceClient,\r\n  ContainerClient,\r\n  RestError,\r\n} from \"@azure/storage-blob\";\r\nimport { DefaultAzureCredential } from \"@azure/identity\";\r\n\r\nconst accountName = process.env.AZURE_STORAGE_ACCOUNT_NAME;\r\nif (!accountName) {\r\n  throw new Error(\r\n    \"AZURE_STORAGE_ACCOUNT_NAME environment variable is not set\"\r\n  );\r\n}\r\n\r\nconst blobServiceClient = new BlobServiceClient(\r\n  `https://${accountName}.blob.core.windows.net`,\r\n  new DefaultAzureCredential()\r\n);\r\n\r\nconst containerName = \"my-container\";\r\nconst blobName = \"greeting.txt\";\r\nconst blobContent = \"Hello Azure!\";\r\n\r\nasync function createContainer(): Promise\u003cContainerClient\u003e {\r\n  console.log(`Creating container \"${containerName}\" if it doesn't exist...`);\r\n  const containerClient = blobServiceClient.getContainerClient(containerName);\r\n  const createResponse = await containerClient.createIfNotExists();\r\n  if (createResponse.succeeded) {\r\n    console.log(`Container \"${containerName}\" created successfully.`);\r\n  } else {\r\n    console.log(`Container \"${containerName}\" already exists.`);\r\n  }\r\n  return containerClient;\r\n}\r\n\r\nasync function uploadBlob(containerClient: ContainerClient): Promise\u003cvoid\u003e {\r\n  console.log(`\\nUploading blob \"${blobName}\"...`);\r\n  const blockBlobClient = containerClient.getBlockBlobClient(blobName);\r\n  const uploadResponse = await blockBlobClient.upload(\r\n    blobContent,\r\n    Buffer.byteLength(blobContent)\r\n  );\r\n  console.log(\r\n    `Blob \"${blobName}\" uploaded successfully. Request ID: ${uploadResponse.requestId}`\r\n  );\r\n}\r\n\r\nasync function listBlobs(containerClient: ContainerClient): Promise\u003cvoid\u003e {\r\n  console.log(`\\nListing blobs in container \"${containerName}\":`);\r\n  for await (const blob of containerClient.listBlobsFlat()) {\r\n    console.log(`  - ${blob.name}`);\r\n  }\r\n}\r\n\r\nasync function downloadBlob(containerClient: ContainerClient): Promise\u003cvoid\u003e {\r\n  console.log(`\\nDownloading blob \"${blobName}\"...`);\r\n  const blockBlobClient = containerClient.getBlockBlobClient(blobName);\r\n  const downloadResponse = await blockBlobClient.download(0);\r\n\r\n  if (!downloadResponse.readableStreamBody) {\r\n    throw new Error(\"Failed to get readable stream from download response\");\r\n  }\r\n\r\n  const downloaded = await streamToString(\r\n    downloadResponse.readableStreamBody\r\n  );\r\n  console.log(`Blob content: \"${downloaded}\"`);\r\n}\r\n\r\nasync function streamToString(\r\n  readableStream: NodeJS.ReadableStream\r\n): Promise\u003cstring\u003e {\r\n  const chunks: Buffer[] = [];\r\n  for await (const chunk of readableStream) {\r\n    chunks.push(Buffer.from(chunk));\r\n  }\r\n  return Buffer.concat(chunks).toString(\"utf-8\");\r\n}\r\n\r\nasync function deleteBlob(containerClient: ContainerClient): Promise\u003cvoid\u003e {\r\n  console.log(`\\nDeleting blob \"${blobName}\"...`);\r\n  const blockBlobClient = containerClient.getBlockBlobClient(blobName);\r\n  await blockBlobClient.delete();\r\n  console.log(`Blob \"${blobName}\" deleted successfully.`);\r\n}\r\n\r\nasync function deleteContainer(\r\n  containerClient: ContainerClient\r\n): Promise\u003cvoid\u003e {\r\n  console.log(`\\nDeleting container \"${containerName}\"...`);\r\n  await containerClient.delete();\r\n  console.log(`Container \"${containerName}\" deleted successfully.`);\r\n}\r\n\r\nasync function main(): Promise\u003cvoid\u003e {\r\n  try {\r\n    const containerClient = await createContainer();\r\n    await uploadBlob(containerClient);\r\n    await listBlobs(containerClient);\r\n    await downloadBlob(containerClient);\r\n    await deleteBlob(containerClient);\r\n    await deleteContainer(containerClient);\r\n\r\n    console.log(\"\\nAll CRUD operations completed successfully.\");\r\n  } catch (error: unknown) {\r\n    if (error instanceof RestError) {\r\n      console.error(`Azure Storage error:`);\r\n      console.error(`  Status code: ${error.statusCode}`);\r\n      console.error(`  Message: ${error.message}`);\r\n      console.error(`  Error code: ${error.code}`);\r\n      console.error(`  Request ID: ${error.request?.requestId}`);\r\n    } else if (error instanceof Error) {\r\n      console.error(`Unexpected error: ${error.message}`);\r\n    } else {\r\n      console.error(\"An unknown error occurred:\", error);\r\n    }\r\n    process.exit(1);\r\n  }\r\n}\r\n\r\nmain();\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2020\",\r\n    \"module\": \"commonjs\",\r\n    \"outDir\": \"dist\",\r\n    \"rootDir\": \"src\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"skipLibCheck\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"resolveJsonModule\": true,\r\n    \"declaration\": true\r\n  },\r\n  \"include\": [\"src/**/*\"]\r\n}\r\n\n```\n\n## Reference Answer\n\nNo reference answer provided.\n\n# Review Scoring Rubric\r\n\r\nYou are a senior Azure SDK code reviewer evaluating generated code.\r\n\r\n## General Criteria\r\n\r\nThese general quality criteria ALWAYS apply to every evaluation. You SHOULD actively verify these where possible (e.g., attempt to build the code, check package versions):\r\n\r\n1. **Code Builds** — Does the generated code compile/build without errors? If you have build tools available, attempt to build it.\r\n2. **Latest Package Versions** — Are the Azure SDK packages the latest stable versions? If you have version-check tools available, verify.\r\n3. **Best Practices** — Does it follow Azure SDK best practices? (DefaultAzureCredential, proper disposal, async patterns, etc.)\r\n4. **Error Handling** — Are errors handled properly? Retries? Timeouts?\r\n5. **Code Quality** — Clean, readable, well-structured code?\r\n\r\n## Prompt-Specific Criteria\r\n\r\nIn addition to general criteria, evaluate each prompt-specific criterion listed in the \"Prompt-Specific Evaluation Criteria\" section (if provided). Each criterion is either MET (passed) or NOT MET (failed).\r\n\r\n## Scoring\r\n\r\nFor EACH criterion (general + prompt-specific), determine:\r\n- **passed**: true if the criterion is fully met, false otherwise\r\n- **reason**: brief explanation of why it passed or failed\r\n\r\nThe overall score = number of passed criteria out of total criteria.\r\n\r\n## Output Format\r\n\r\nRespond with ONLY a JSON object, no markdown fencing, no explanation:\r\n\r\n```json\r\n{\"scores\":{\"criteria\":[{\"name\":\"criterion name\",\"passed\":true,\"reason\":\"brief explanation\"},{\"name\":\"another criterion\",\"passed\":false,\"reason\":\"why it failed\"}]},\"overall_score\":N,\"max_score\":N,\"summary\":\"...\",\"issues\":[\"...\"],\"strengths\":[\"...\"]}\r\n```\r\n\r\nWhere overall_score = count of passed criteria, max_score = total criteria count.\r\n"
